sol = [0, 1, 33, 2, 32, 5, 25, 3, 29, 4, 18, 13, 14, 6, 31, 7, 26, 20]
# Cliques: (0,1,2), (3,4,5), ..., (15,16,17)
def v(g,i): return g*3+i
edges = []
for g in range(6):
    for i in range(3):
        for j in range(i+1,3):
            edges.append((v(g,i),v(g,j)))
for g in range(5):
    for i in range(3):
        edges.append((v(g,i),v(g+1,i)))
ds = [abs(sol[a]-sol[b]) for a,b in edges]
print(len(ds), len(set(ds)), min(ds), max(ds))
print(len(set(sol)), min(sol), max(sol))
